source:
\begin{prop}\ollabel{prop:graph-function}
Let $R \subseteq A \times B$ be such that:
\begin{enumerate}
\item If $Rxy$ and $Rxz$ then $y = z$; and 
\item for every $x \in A$ there is some $y \in B$ such that $\tuple{x,
y} \in R$.  
\end{enumerate}
Then $R$ is the graph of the function $f\colon A \to B$ defined by
$f(x) = y$ iff $Rxy$. 
\end{prop}

target:
\begin{prop}\ollabel{prop:graph-function}
فرض کړئ $R \subseteq A \times B$ داسې ده چې:
\begin{enumerate}
\item که $Rxy$ او $Rxz$ وي، نو $y = z$ وي؛ او
\item د هر $x \in A$ دپاره داسې $y \in B$ شته چې $\tuple{x,
y} \in R$ وي۔
\end{enumerate}
نو $R$ د هغې تابعې $f\colon A \to B$ ګراف ده چې په دې ډول
تعريف شوې ده: $f(x) = y$ هله او يوازې هله چې $Rxy$ وي۔
\end{prop}

source:
\begin{proof}
Suppose there is a $y$ such that $Rxy$.  If there were another $z \neq
y$ such that $Rxz$, the condition on~$R$ would be violated. Hence, if
there is a $y$ such that $Rxy$, this $y$ is unique, and so $f$ is
well-defined.  Obviously, $R_f = R$.
\end{proof}

target:
\begin{proof}
فرض کړئ داسې $y$ شته چې $Rxy$ وي۔ که يو بل $z \neq y$ هم واے
چې $Rxz$ واے، پر~$R$ لګېدلے شرط به مات شوے و۔ نو که داسې $y$
شته چې $Rxy$ وي، دا $y$ يوازينے دے؛ له دې کبله~$f$ په سمه توګه
تعريف شوې ده۔ په ښکاره، $R_f = R$۔
\end{proof}

په~$C$ باندې د~$f$ \emph{تطبيق} دا دے: $\funimage{f}{C} =
\Setabs{f(x)}{x \in C}$۔ دې ته د~$f$ لاندې د~$C$ \emph{انځور} هم وايو۔
\end{defn}

source:
\begin{explain}
It follows from these definitions that $\ran{f} =
\funimage{f}{\dom{f}}$, for any function~$f$.
\oliflabeldef{sfr:rel:ops:sec}{These notions are exactly as one would
expect, given the definitions in \olref[sfr][rel][ops]{sec} and our
identification of functions with relations. But two other
operations---inverses and relative products---require a little more
detail. We will provide that in \olref[inv]{sec} and
\olref[cmp]{sec}.}{}
\end{explain}

target:
\begin{explain}
له دې تعريفونو څرګندېږي چې د هرې تابعې~$f$ دپاره
$\ran{f} = \funimage{f}{\dom{f}}$۔
\oliflabeldef{sfr:rel:ops:sec}{په \olref[sfr][rel][ops]{sec} کښې د
تعريفونو او له اړيکو سره د تابعو د يو ګڼلو له مخې، ورته
مفهومونه مو تمه لرله۔ دلته د تابعې محدودونه يوازې د ننوت
مختصات محدودوي؛ د اړيکې مخکښ تعريف دواړه مختصات محدودوي۔
خو دوه نور عمليات---معکوسونه او نسبي
حاصل ضربونه---لږ زيات تفصيل غواړي۔ هغه به په \olref[inv]{sec}
او \olref[cmp]{sec} کښې وړاندې کړو۔}{}
\end{explain}

source:
\begin{defn}
A function $g \colon B \to A$ is an \emph{inverse} of a function $f
\colon A \to B$ if $f(g(y)) = y$ and $g(f(x)) = x$ for all $x \in A$
and $y \in B$.
\end{defn}

target:
\begin{defn}
تابع $g \colon B \to A$ د تابعې $f \colon A \to B$ \emph{معکوس}
ده که د ټولو $x \in A$ او $y \in B$ دپاره $f(g(y)) = y$ او
$g(f(x)) = x$ وي۔
\end{defn}

source:
\begin{prop}
If $f\colon A \to B$ is !!{injective}, then there is a \emph{left
inverse}~$g\colon B \to A$ of~$f$ so that $g(f(x)) = x$ for all $x
\in A$.
\end{prop}

\begin{prob}
Show that if $f\colon A \to B$ has a left inverse~$g$, then $f$~is
!!{injective}.
\end{prob}

target:
\begin{prob}
وښيئ چې که $f\colon A \to B$ کيڼ معکوس~$g$ ولري، نو~$f$
!!{injective} ده۔
\end{prob}

source:
\begin{prop}
    If $f\colon A \to B$ is !!{surjective}, then there is a
    \emph{right inverse}~$h\colon B \to A$ of~$f$ so that $f(h(y)) =
    y$ for all~$y \in B$.
\end{prop}

target:
\begin{prop}
    که $f\colon A \to B$ يوه !!{surjective} تابع وي، نو د~$f$
    يو \emph{ښي معکوس}~$h\colon B \to A$ شته چې د ټولو~$y \in B$
    دپاره $f(h(y)) = y$ وي۔
\end{prop}

source:
\begin{prob}
Show that if $f\colon A \to B$ has a right inverse~$h$, then $f$~is
!!{surjective}.
\end{prob}

target:
\begin{prob}
وښيئ چې که $f\colon A \to B$ ښي معکوس~$h$ ولري، نو~$f$
!!{surjective} ده۔
\end{prob}

source:
\begin{explain}
  By combining the ideas in the previous proof, we now get that every
  !!{bijection} has an inverse, i.e., there is a single function
  which is both a left and right inverse of~$f$.
\end{explain}

target:
\begin{explain}
  د مخکيني ثبوت د مفکورو په يوځاے کولو اوس دا ترلاسه کوو چې
  هره !!{bijection} معکوس لري؛ يعنې يوه واحده تابع شته چې
  هم د~$f$ کيڼ معکوس دے او هم ښي معکوس۔
\end{explain}

source:
\begin{prop}\ollabel{prop:bijection-inverse}
If $f\colon A \to B$ is !!{bijective}, there is a
function~$f^{-1}\colon B \to A$ so that for all $x \in A$,
$f^{-1}(f(x)) = x$ and for all $y \in B$, $f(f^{-1}(y)) = y$.
\end{prop}

target:
\begin{prop}\ollabel{prop:bijection-inverse}
که $f\colon A \to B$ يوه !!{bijective} تابع وي، داسې تابع
$f^{-1}\colon B \to A$ شته چې د ټولو $x \in A$ دپاره
$f^{-1}(f(x)) = x$ او د ټولو $y \in B$ دپاره $f(f^{-1}(y)) = y$ وي۔
\end{prop}

source:
\begin{proof}
Exercise.
\end{proof}

target:
\begin{proof}
تمرين۔
\end{proof}

source:
\begin{prob}
Prove \olref[sfr][fun][inv]{prop:bijection-inverse}. You have to
define~$f^{-1}$, show that it is a function, and show that it is an
inverse of~$f$, i.e., $f^{-1}(f(x)) = x$ and $f(f^{-1}(y)) = y$ for
all $x \in A$ and $y \in B$.
\end{prob}

target:
\begin{prob}
\olref[sfr][fun][inv]{prop:bijection-inverse} ثابته کړئ۔ بايد
$f^{-1}$ تعريف کړئ، وښيئ چې تابع ده، او وښيئ چې د~$f$ معکوس
ده؛ يعنې د ټولو $x \in A$ او $y \in B$ دپاره $f^{-1}(f(x)) = x$
او $f(f^{-1}(y)) = y$ وي۔
\end{prob}

\begin{explain}
د معکوسونو د ترلاسه کولو يوه لږه زياته عمومي لار هم شته۔ په
\olref[kin]{sec} کښې مو وليدل چې هره تابع $f$ د ټولو $x \in A$
دپاره د $f'(x) = f(x)$ په ټاکلو سره يوه !!a{surjection}
$f' \colon A \to \ran{f}$ رامنځته کوي۔ په ښکاره، که~$f$
!!{injective} وي، نو~$f'$ !!{bijective} ده، او له دې کبله د
\olref{prop:bijection-inverse} له مخې يوازينے معکوس لري۔ د نښو
په کارولو کښې په يو ډېر واړه تسامح سره، کله کله د $f'$ معکوس
يوازې «د~$f$ معکوس» بولو۔
\end{explain}

