\begin{defn}
A \emph{Dedekind algebra} is a set $A$ together with a function $f
\colon A \to A$ and some $o \in A$  such that:
	\begin{enumerate}
		\item \ollabel{ded:proper} $o \notin \ran{f}$
		\item \ollabel{ded:injection} $f$ is !!a{injection}
		\item \ollabel{ded:closure} $A = \closureofunder{f}{o}$
	\end{enumerate}
\end{defn}

target:
\begin{defn}
د \emph{ډېډېکېنډ الجبر} يو سټ $A$، يوه تابع $f \colon A \to A$ او
يو $o \in A$ دي چې لاندې شرطونه پوره کوي:
	\begin{enumerate}
		\item \ollabel{ded:proper} $o \notin \ran{f}$
		\item \ollabel{ded:injection} $f$ يوه !!a{injection} ده
		\item \ollabel{ded:closure} $A = \closureofunder{f}{o}$
	\end{enumerate}
\end{defn}

