\end{prop}

source:
\begin{proof}
Suppose $!A$ is atomic. Then the sequence~$\tuple{!A}$ is a
formation sequence for~$!A$.
%
Now suppose that $!B$ and~$!C$ have formation sequences
$\tuple{!B_0,\dotsc,!B_n}$ and $\tuple{!C_0,\dotsc,!C_m}$
respectively.
%
\begin{enumerate}
  \tagitem{prvNot}{If $!A \ident \lnot !B$,
      then $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvAnd}{If $!A \ident (!B \land !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvOr}{If $!A \ident (!B \lor !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIf}{If $!A \ident (!B \lif !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIff}{If $!A \ident (!B \liff !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      is a formation sequence for~$!A$.}{}
\end{enumerate}
By the principle of induction on !!{formula}s,
every !!{formula} has a formation sequence.
\end{proof}

target:
\begin{proof}
فرض کړئ $!A$ اټومي دے۔ نو لړۍ~$\tuple{!A}$ د~$!A$ جوړښتي لړۍ ده۔
%
اوس فرض کړئ چې $!B$ او~$!C$ په ترتيب سره جوړښتي لړۍ
$\tuple{!B_0,\dotsc,!B_n}$ او $\tuple{!C_0,\dotsc,!C_m}$ لري۔
%
\begin{enumerate}
  \tagitem{prvNot}{که $!A \ident \lnot !B$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvAnd}{که $!A \ident (!B \land !C)$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvOr}{که $!A \ident (!B \lor !C)$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvIf}{که $!A \ident (!B \lif !C)$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
  \tagitem{prvIff}{که $!A \ident (!B \liff !C)$ وي، نو
      $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      د~$!A$ جوړښتي لړۍ ده۔}{}
\end{enumerate}
د !!{formula}s دپاره د استقرا د اصل له مخې، هر !!{formula} يوه
جوړښتي لړۍ لري۔
\end{proof}

