\begin{prop}[Compactness]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

target:
\begin{prop}[تراکم]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item که $\Gamma \Proves !A$ وي، نو داسې متناهي فرعي سټ
    $\Gamma_0 \subseteq \Gamma$ شته چې $\Gamma_0 \Proves !A$ وي۔
  \item که د~$\Gamma$ هر متناهي فرعي سټ سازګار وي، نو $\Gamma$
    سازګار دے۔
  \end{enumerate}
\end{prop}

source:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is
      !!a{derivation}~$\delta$ of~$!A$ from~$\Gamma$. Let $\Gamma_0$
      be the set of !!{undischarged} assumptions of~$\delta$.  Since
      any !!{derivation} is finite, $\Gamma_0$ can only contain
      finitely many !!{sentence}s.  So, $\delta$ is !!a{derivation}
      of~$!A$ from a finite~$\Gamma_0 \subseteq \Gamma$.
    \item This is the contrapositive of (1) for the special case $!A
      \ident \lfalse$.
  \end{enumerate}
\end{proof}

target:
\begin{proof}
  \begin{enumerate}
    \item که $\Gamma \Proves !A$ وي، نو له~$\Gamma$ څخه د~$!A$
      کوم !!a{derivation}~$\delta$ شته۔ $\Gamma_0$ د~$\delta$ د
      !!{undischarged} فرضيو سټ ونيسئ۔ ځکه هر !!{derivation} متناهي
      دے، $\Gamma_0$ يوازې متناهي ډېرې !!{sentence}s لرلے شي۔ نو
      $\delta$ له متناهي~$\Gamma_0 \subseteq \Gamma$ څخه د~$!A$
      !!a{derivation} دے۔
    \item دا د~(۱) د هغه ځانګړي حالت نقيض عکس دے چې
      $!A \ident \lfalse$ وي۔
  \end{enumerate}
\end{proof}

