We will now establish a number of properties of the !!{derivability}
relation.  They are independently interesting, but each will play a
role in the proof of the completeness theorem.

\begin{prop}\ollabel{prop:provability-contr}
  If $\Gamma \Proves !A$ and $\Gamma \cup \{!A\}$ is inconsistent,
  then $\Gamma$ is inconsistent.
\end{prop}

target:
\begin{prop}\ollabel{prop:provability-contr}
  که $\Gamma \Proves !A$ وي او $\Gamma \cup \{!A\}$ ناسازګار وي،
  نو $\Gamma$ ناسازګار دے۔
\end{prop}

source:
\begin{proof}
Let the !!{derivation} of~$!A$ from~$\Gamma$ be~$\delta_1$ and the
!!{derivation} of~$\lfalse$ from $\Gamma \cup \{!A\}$
be~$\delta_2$. We can then !!{derive}:
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\AxiomC{$\Gamma$}
\RightLabel{$\delta_1$}
\DeduceC{$!A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
In the new !!{derivation}, the assumption~$!A$ is !!{discharged}, so it is
!!a{derivation} from~$\Gamma$.
\end{proof}

target:
\begin{proof}
له~$\Gamma$ څخه د~$!A$ !!{derivation}~$\delta_1$ او له
$\Gamma \cup \{!A\}$ څخه د~$\lfalse$ !!{derivation}~$\delta_2$
ونوموئ۔ بيا داسې !!{derive} کولے شو:
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\AxiomC{$\Gamma$}
\RightLabel{$\delta_1$}
\DeduceC{$!A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
په نوي !!{derivation} کښې فرضيه~$!A$~!!{discharged} شوې ده، نو دا
له~$\Gamma$ څخه !!a{derivation} دے۔
\end{proof}

source:
\begin{prop}
\ollabel{prop:prov-incons}
$\Gamma \Proves !A$ iff $\Gamma \cup \{\lnot !A\}$ is inconsistent.
\end{prop}

target:
\begin{prop}
\ollabel{prop:prov-incons}
$\Gamma \Proves !A$ هله او يوازې هله چې
$\Gamma \cup \{\lnot !A\}$ ناسازګار وي۔
\end{prop}

source:
\begin{proof}
First suppose $\Gamma \Proves !A$, i.e., there is
!!a{derivation}~$\delta_0$ of~$!A$ from !!{undischarged}
assumptions~$\Gamma$. We obtain !!a{derivation} of $\lfalse$ from
$\Gamma \cup \{\lnot !A\}$ as follows:
\begin{prooftree}
  \AxiomC{$\lnot !A$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lnot}}
  \BinaryInfC{$\lfalse$}
\end{prooftree}

target:
\begin{proof}
لومړے فرض کړئ $\Gamma \Proves !A$؛ يعنې د~$!A$ داسې
!!a{derivation}~$\delta_0$ شته چې !!{undischarged} فرضيې ئې
$\Gamma$ دي۔ له~$\Gamma \cup \{\lnot !A\}$ څخه د~$\lfalse$ يو
!!a{derivation} داسې اخلو:
\begin{prooftree}
  \AxiomC{$\lnot !A$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lnot}}
  \BinaryInfC{$\lfalse$}
\end{prooftree}

source:
Now assume $\Gamma \cup \{\lnot !A\}$ is inconsistent, and let
$\delta_1$ be the corresponding !!{derivation} of~$\lfalse$ from
!!{undischarged} assumptions in~$\Gamma \cup \{\lnot !A\}$. We obtain
!!a{derivation} of~$!A$ from~$\Gamma$ alone by using~$\FalseCl$:
\begin{prooftree}
  \AxiomC{$\Gamma, \Discharge{\lnot !A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$\lfalse$}
  \RightLabel{\FalseCl}
  \DischargeRule{\FalseCl}{1}
  \UnaryInfC{$!A$}
\end{prooftree}
\end{proof}

target:
اوس فرض کړئ $\Gamma \cup \{\lnot !A\}$ ناسازګار دے، او
$\delta_1$ له~$\Gamma \cup \{\lnot !A\}$ کښې له !!{undischarged}
فرضيو څخه د~$\lfalse$ اړوند !!{derivation} دے۔ يوازې له~$\Gamma$
څخه د~$!A$ يو !!a{derivation} د~$\FalseCl$ په کارولو اخلو:
\begin{prooftree}
  \AxiomC{$\Gamma, \Discharge{\lnot !A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$\lfalse$}
  \DischargeRule{\FalseCl}{1}
  \UnaryInfC{$!A$}
\end{prooftree}
\textbf{د ژباړې د نسخې سمون (OLND-005):} سرچينه په دې ونه کښې
له ايستلو نښان سره د همدې قاعدې يو دويم ښي نښان هم ږدي؛ زيات نښان
لرې شوے او د فرضيې ايستل او د قاعدې نوم په ټاکلي ګډ نښان کښې ساتل
شوي دي۔
\end{proof}

