\begin{prop}[Reflexivity]
\ollabel{prop:reflexivity}
If $!A \in \Gamma$, then $\Gamma \Proves !A$.
\end{prop}

target:
\begin{prop}[انعکاسيت]
\ollabel{prop:reflexivity}
که $!A \in \Gamma$ وي، نو $\Gamma \Proves !A$۔
\end{prop}

source:
\begin{proof}
If $!A \in \Gamma$, $\{!A\}$ is a finite subset of~$\Gamma$ and the !!{tableau}
\begin{oltableau}
  [\sFmla{\False}{\formula{A}}, just = \TAss
    [\sFmla{\True}{\formula{A}}, just = \TAss,close]
  ]
\end{oltableau}
is closed.
\end{proof}

target:
\begin{proof}
که $!A \in \Gamma$ وي، نو $\{!A\}$ د~$\Gamma$ يو متناهي فرعي سټ
دے، او لاندې !!{tableau} تړلے دے:
\begin{oltableau}
  [\sFmla{\False}{\formula{A}}, just = \TAss
    [\sFmla{\True}{\formula{A}}, just = \TAss,close]
  ]
\end{oltableau}
\end{proof}

source:
\begin{prop}[Monotonicity]
\ollabel{prop:monotonicity}
If $\Gamma \subseteq \Delta$ and $\Gamma \Proves !A$, then $\Delta
\Proves !A$.
\end{prop}

target:
\begin{prop}[يکنواختي]
