\begin{prop}[Compactness]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

target:
\begin{prop}[تراکم]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item که $\Gamma \Proves !A$ وي، نو داسې متناهي فرعي سټ
    $\Gamma_0 \subseteq \Gamma$ شته چې $\Gamma_0 \Proves !A$ وي۔
  \item که د~$\Gamma$ هر متناهي فرعي سټ سازګار وي، نو $\Gamma$
    سازګار دے۔
  \end{enumerate}
\end{prop}

source:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is a finite subset
      $\Gamma_0 = \{!B_1, \dots, !B_n\}$ and a closed !!{tableau} for
      \[
      \{\sFmla{\False}{!A}, \sFmla{\True}{!B_1}, \dots, \sFmla{\True}{!B_n}\}
      \]
      This !!{tableau} also shows $\Gamma_0 \Proves !A$.
    \item If $\Gamma$ is inconsistent, then for some finite subset
      $\Gamma_0 = \{!B_1, \dots, !B_n\}$ there is a closed !!{tableau}
      for
      \[
      \{\sFmla{\True}{!B_1}, \dots, \sFmla{\True}{!B_n}\}
      \]
      This closed !!{tableau} shows that $\Gamma_0$ is inconsistent.
  \end{enumerate}
\end{proof}

target:
\begin{proof}
  \begin{enumerate}
    \item که $\Gamma \Proves !A$ وي، نو داسې متناهي فرعي سټ
      $\Gamma_0 = \{!B_1, \dots, !B_n\}$ او د لاندې دپاره تړلے
      !!{tableau} شته:
      \[
      \{\sFmla{\False}{!A}, \sFmla{\True}{!B_1}, \dots, \sFmla{\True}{!B_n}\}
      \]
      همدا !!{tableau}، $\Gamma_0 \Proves !A$ هم ښيي۔
    \item که $\Gamma$ ناسازګار وي، نو د کوم متناهي فرعي سټ
      $\Gamma_0 = \{!B_1, \dots, !B_n\}$ دپاره د لاندې يو تړلے
      !!{tableau} شته:
      \[
      \{\sFmla{\True}{!B_1}, \dots, \sFmla{\True}{!B_n}\}
      \]
      دا تړلے !!{tableau} ښيي چې $\Gamma_0$ ناسازګار دے۔
  \end{enumerate}
\end{proof}

