source:
\begin{prop}[Compactness]
\ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

target:
\begin{prop}[تراکم]
\ollabel{prop:proves-compact}
  \begin{enumerate}
  \item که $\Gamma \Proves !A$ وي، نو داسې متناهي فرعي سټ
    $\Gamma_0 \subseteq \Gamma$ شته چې $\Gamma_0 \Proves !A$۔
  \item که د~$\Gamma$ هر متناهي فرعي سټ سازګار وي، نو $\Gamma$
    سازګار دے۔
  \end{enumerate}
\end{prop}

source:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is a finite sequence of
      !!{formula}s $!A_1$, \dots,~$!A_n$ so that $!A \ident !A_n$ and
      each $!A_i$ is either a logical axiom, !!a{element} of~$\Gamma$
      or follows from previous !!{formula}s by modus ponens.  Take
      $\Gamma_0$ to be those $!A_i$ which are in~$\Gamma$.  Then the
      !!{derivation} is likewise !!a{derivation} from~$\Gamma_0$, and
      so $\Gamma_0 \Proves !A$.
    \item This is the contrapositive of~(1) for the special case $!A
      \ident \lfalse$.
\end{enumerate}
\end{proof}

target:
\begin{proof}
  \begin{enumerate}
    \item که $\Gamma \Proves !A$ وي، نو د !!{formula}s داسې متناهي
      لړۍ $!A_1$، \dots،~$!A_n$ شته چې $!A \ident !A_n$؛ او هر
      $!A_i$ يا منطقي بديهي اصل وي، يا د~$\Gamma$ يو !!a{element}
      وي، يا د مودوس پوننس له مخې له مخکښو !!{formula}s څخه راځي۔
      $\Gamma_0$ د هغو $!A_i$ سټ ونيسئ چې په~$\Gamma$ کښې دي۔ بيا
      همدا !!{derivation} له~$\Gamma_0$ څخه هم يو !!a{derivation}
      دے، نو $\Gamma_0 \Proves !A$۔
    \item دا د ځانګړي حالت~$!A \ident \lfalse$ دپاره د~(۱) مقابل
      عکس دے۔
\end{enumerate}
\end{proof}

