\]
\end{defn}
}

source:
\begin{lem} 
\ollabel{lem:val-in-termmodel} Let $\Struct M(\Gamma^*)$ be the term model
of \olref{defn:termmodel}, then $\Value{t}{M(\Gamma^*)} = t$.
\end{lem}
\begin{proof} 
 The proof is by induction on $t$, where the base case, when $t$
 is !!a{constant}, follows directly from the definition of the term
 model. For the induction step assume $t_1, \ldots, t_n$ are closed terms
 such that $\Value{t_i}{M(\Gamma^*)} = t_i$ and that $f$ is an $n$-ary
 !!{function}. Then 
\begin{align*}
\Value{f(t_1,\ldots,t_n)}{M(\Gamma^*)} &= \Assign{f}{M(\Gamma^*)}(\Value{t_1}
 {M(\Gamma^*)}, 
\ldots, \Value{t_n}{M(\Gamma^*)}) \\
&= \Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) \\
&= f(t_1,\dots, t_n),
\end{align*} 
and so by induction this holds for every closed term~$t$.
\end{proof}
}

target:
\begin{lem}
\ollabel{lem:val-in-termmodel} فرض کړئ~$\Struct M(\Gamma^*)$ د
\olref{defn:termmodel} ترمي مدل دے؛ بيا د هر تړلي ترم دپاره
$\Value{t}{M(\Gamma^*)} = t$۔
\end{lem}
\begin{proof}
 ثبوت پر~$t$ د استقرا له لارې دے۔ د بنسټ حالت، چې~$t$
 يو !!a{constant} وي، نېغ په نېغه د ترمي مدل له تعريف څخه ترلاسه
 کېږي۔ د استقرا د ګام دپاره فرض کړئ~$t_1, \ldots, t_n$ داسې تړلي
 ترمونه دي چې~$\Value{t_i}{M(\Gamma^*)} = t_i$، او~$f$ يوه
 $n$-مقامي !!{function} ده۔ بيا
\begin{align*}
\Value{f(t_1,\ldots,t_n)}{M(\Gamma^*)} &= \Assign{f}{M(\Gamma^*)}(\Value{t_1}
 {M(\Gamma^*)},
\ldots, \Value{t_n}{M(\Gamma^*)}) \\
&= \Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) \\
&= f(t_1,\dots, t_n),
\end{align*}
او نو د استقرا له مخې دا د هر تړلي ترم~$t$ دپاره سم دي۔
\end{proof}
\textbf{د ژباړې د نسخې سمون (OLCOM-008):} په سرچينه کښې د دې
ټاکنيز شرط درېيم (د لومړۍ درجې منطق د نۀ ټاکل کېدو) تش ارګومېنټ پاتې شوے و؛
دلته په څرګنده توګه ورزيات شو، څو راتلونکے شرط د هغه پر ځاے وانۀ
خيستل شي۔
}{}

