\begin{cor}[Completeness Theorem, Second Version]
\ollabel{cor:completeness}
For all $\Gamma$ and !!{sentence}s~$!A$: if $\Gamma \Entails !A$ then
$\Gamma \Proves !A$.
\end{cor}

target:
