\begin{defn}
  A set $\Gamma$ of !!{formula}s is \emph{finitely satisfiable} iff every finite $\Gamma_0 \subseteq \Gamma$ is satisfiable.
\end{defn}

target:
\begin{defn}
  د~!!{formula}s يو سټ~$\Gamma$ هله او يوازې هله
  \emph{په متناهي ډول د صدق وړ} دے چې هر متناهي
  $\Gamma_0 \subseteq \Gamma$ د صدق وړ وي۔
\end{defn}

source:
\begin{thm}[Compactness Theorem]
\ollabel{thm:compactness}
The following hold for any sentences $\Gamma$ and $!A$:
\begin{enumerate}
  \item $\Gamma \Entails !A$ iff there is a finite $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Entails !A$.
  \item $\Gamma$ is satisfiable iff it is finitely
    satisfiable.
\end{enumerate}
\end{thm}

target:
\begin{thm}[د متناهي شاهد قضيه]
\ollabel{thm:compactness}
د هرې د جملو ټولګې~$\Gamma$ او هرې جملې~$!A$ دپاره لاندې خبرې سمې دي:
\begin{enumerate}
  \item $\Gamma \Entails !A$ هله او يوازې هله چې يو متناهي
    $\Gamma_0 \subseteq \Gamma$ وي، داسې چې
    $\Gamma_0 \Entails !A$۔
  \item $\Gamma$ هله او يوازې هله د صدق وړ دے چې په متناهي ډول
    د صدق وړ وي۔
\end{enumerate}
\end{thm}

