\begin{prop}
\ollabel{prop:fsat-ccs}
Suppose $\Gamma$ is !!{complete} and finitely satisfiable. Then:
\begin{enumerate}
\tagitem{prvAnd}{$(!A \land !B) \in \Gamma$
  iff both $!A \in \Gamma$ and $!B \in \Gamma$.}{}

target:
