source:
\begin{thm} 
\ollabel{thm:downward-ls} If $\Gamma$ is consistent then it has
!!a{enumerable} model, i.e., it is satisfiable in !!a{structure}
whose domain is either finite or !!{denumerable}.
\end{thm}

target:
\begin{thm}
\ollabel{thm:downward-ls} که~$\Gamma$ سازګار وي، نو يو
!!a{enumerable} مدل لري؛ يعنې په داسې !!a{structure} کښې د صدق وړ
دے چې د تعريف ساحه ئې يا متناهي يا !!{denumerable} وي۔
\end{thm}

source:
\begin{proof}
If $\Gamma$ is consistent, the !!{structure}~$\Struct M$ delivered by
the proof of the completeness theorem has a domain $\Domain{M}$ that
is no larger than the set of the terms of the language~$\Lang L$. So
$\Struct M$ is at most !!{denumerable}.
\end{proof}

target:
\begin{proof}
که~$\Gamma$ سازګار وي، د بشپړتيا قضيې ثبوت چې کوم
!!{structure}~$\Struct M$ ورکوي، د هغه د تعريف ساحه~$\Domain{M}$
د ژبې~$\Lang L$ د ترمونو له سټ څخه لويه نۀ ده۔ نو~$\Struct M$ تر
ډېره !!{denumerable} دے۔
\end{proof}

source:
\begin{thm}
\ollabel{noidentity-ls} If $\Gamma$ is a consistent set of !!{sentence}s
in the language of first-order logic without identity, then it has
!!a{denumerable} model, i.e., it is satisfiable in !!a{structure}
whose domain is infinite and !!{enumerable}.
\end{thm}

target:
\begin{thm}
\ollabel{noidentity-ls} که~$\Gamma$ د عينيت پرته د اول مرتبې د
منطق په ژبه کښې د~!!{sentence}s يو سازګار سټ وي، نو يو
!!a{denumerable} مدل لري؛ يعنې په داسې !!a{structure} کښې د صدق وړ
دے چې د تعريف ساحه ئې نامتناهي او !!{enumerable} وي۔
\end{thm}
